def concept(
    id: str,
    label_ko: str,
    aliases: list[str],
    concept_type: str,
    short_definition: str,
    source_refs: list[dict],
    prerequisite_ids: list[str] | None = None,
    parent_ids: list[str] | None = None,
    related_ids: list[str] | None = None,
    notes: str = "",
    confidence: str = "high",
    grade: str = "중1(교육과정 학년군: 중1-3)",
    domain: str = "변화와 관계",
    unit: str = "좌표평면과 그래프",
) -> dict:
    return {
        "id": id,
        "label_ko": label_ko,
        "aliases": aliases,
        "grade": grade,
        "domain": domain,
        "unit": unit,
        "concept_type": concept_type,
        "short_definition": short_definition,
        "source_refs": source_refs,
        "prerequisite_ids": prerequisite_ids or [],
        "parent_ids": parent_ids or [],
        "related_ids": related_ids or [],
        "notes": notes,
        "confidence": confidence,
    }


def geo_concept(
    id: str,
    label_ko: str,
    aliases: list[str],
    concept_type: str,
    short_definition: str,
    source_refs: list[dict],
    prerequisite_ids: list[str] | None = None,
    parent_ids: list[str] | None = None,
    related_ids: list[str] | None = None,
    notes: str = "",
    confidence: str = "high",
    grade: str = "중1(교육과정 학년군: 중1-3)",
    unit: str = "기본 도형",
) -> dict:
    return concept(
        id,
        label_ko,
        aliases,
        concept_type,
        short_definition,
        source_refs,
        prerequisite_ids=prerequisite_ids,
        parent_ids=parent_ids,
        related_ids=related_ids,
        notes=notes,
        confidence=confidence,
        grade=grade,
        domain="도형과 측정",
        unit=unit,
    )


def data_concept(
    id: str,
    label_ko: str,
    aliases: list[str],
    concept_type: str,
    short_definition: str,
    source_refs: list[dict],
    prerequisite_ids: list[str] | None = None,
    parent_ids: list[str] | None = None,
    related_ids: list[str] | None = None,
    notes: str = "",
    confidence: str = "high",
    grade: str = "중1(교육과정 학년군: 중1-3)",
    unit: str = "자료와 가능성",
) -> dict:
    return concept(
        id,
        label_ko,
        aliases,
        concept_type,
        short_definition,
        source_refs,
        prerequisite_ids=prerequisite_ids,
        parent_ids=parent_ids,
        related_ids=related_ids,
        notes=notes,
        confidence=confidence,
        grade=grade,
        domain="자료와 가능성",
        unit=unit,
    )


