CONCEPTS.extend(DATA_CONCEPTS)


def edge(
    source_id: str,
    target_id: str,
    relationship_type: str,
    source_refs: list[dict],
    notes: str = "",
    confidence: str = "high",
) -> dict:
    return {
        "id": f"{source_id}__{relationship_type}__{target_id}",
        "source_id": source_id,
        "target_id": target_id,
        "relationship_type": relationship_type,
        "source_refs": source_refs,
        "notes": notes,
        "confidence": confidence,
    }


SEMANTIC_RELATED_EDGE_TYPES = {
    "related_to",
    "equivalent_to",
    "contrasts_with",
    "often_confused_with",
    "represented_by",
    "used_in",
}


def append_missing_edges_from_concept_array(array_field: str, relationship_type: str) -> None:
    existing = {
        (item["source_id"], item["target_id"], item["relationship_type"])
        for item in EDGES
    }
    for item in CONCEPTS:
        for source_id in item[array_field]:
            key = (source_id, item["id"], relationship_type)
            if key in existing:
                continue
            EDGES.append(
                edge(
                    source_id,
                    item["id"],
                    relationship_type,
                    item["source_refs"],
                    confidence=item["confidence"],
                )
            )
            existing.add(key)


def append_missing_concept_array_entries_from_edges(relationship_type: str, array_field: str) -> None:
    concepts_by_id = {item["id"]: item for item in CONCEPTS}
    for item in EDGES:
        if item["relationship_type"] != relationship_type:
            continue
        target = concepts_by_id[item["target_id"]]
        if item["source_id"] not in target[array_field]:
            target[array_field].append(item["source_id"])


def append_missing_misconception_related_edges() -> None:
    concepts_by_id = {item["id"]: item for item in CONCEPTS}
    existing_pairs = {
        frozenset([item["source_id"], item["target_id"]])
        for item in EDGES
        if item["relationship_type"] == "often_confused_with"
    }
    for item in CONCEPTS:
        for related_id in item["related_ids"]:
            related = concepts_by_id[related_id]
            if item["concept_type"] != "misconception_risk" and related["concept_type"] != "misconception_risk":
                continue
            pair = frozenset([item["id"], related_id])
            if pair in existing_pairs:
                continue
            if item["concept_type"] == "misconception_risk":
                risk = item
                counterpart = related
            else:
                risk = related
                counterpart = item
            EDGES.append(
                edge(
                    risk["id"],
                    counterpart["id"],
                    "often_confused_with",
                    risk["source_refs"] or counterpart["source_refs"],
                    notes="related_ids에서 확인된 오개념 위험 연결을 낮은 신뢰도 edge로 보강. 교과서 근거 확인 후 유지 또는 조정.",
                    confidence="low",
                )
            )
            existing_pairs.add(pair)


def prune_structural_related_ids_without_semantic_edge() -> None:
    structural_pairs = {
        frozenset([item["source_id"], item["target_id"]])
        for item in EDGES
        if item["relationship_type"] in {"contains", "prerequisite_for"}
    }
    semantic_pairs = {
        frozenset([item["source_id"], item["target_id"]])
        for item in EDGES
        if item["relationship_type"] in SEMANTIC_RELATED_EDGE_TYPES
    }
    for item in CONCEPTS:
        item["related_ids"] = [
            related_id
            for related_id in item["related_ids"]
            if frozenset([item["id"], related_id]) not in structural_pairs
            or frozenset([item["id"], related_id]) in semantic_pairs
        ]


